int partition(int L, int R, int index){
    int pivot = c[index];
    swapEdge(index,R);
    int storeIndex = L;
    for(int i = L; i <= R-1; i++){
       if(c[i] < pivot){
           swapEdge(storeIndex,i);
           storeIndex++;
       }
    }
    swapEdge(storeIndex,R);
    return storeIndex;
}

