Shortest Path Problem - Dijkstra
void swap(int i, int j){
    int tmp = node[i]; node[i] = node[j]; node[j] = tmp;
    idx[node[i]] = i; idx[node[j]] = j;
}
void upHeap(int i){
    if(i == 0) return;
    while(i > 0){
       int pi = (i-1)/2;
       if(d[node[i]] < d[node[pi]]){
           swap(i,pi);
       }else{
           break;
       }
       i = pi;
    }
}
